/* Demonstração independente: todos os registros são fictícios e vivem na memória. */
'use strict';
const categories=['Contratos','Trabalhista','Consumidor','Cível','Societário','Compliance','LGPD','Notificação','Parecer','Consultivo','Processo judicial','Outros'];
const statuses=['Nova','Em análise','Aguardando Jurídico','Aguardando MG Cred','Em andamento','Concluída','Arquivada'];
const now=new Date();
const day=(offset)=>{const d=new Date(now);d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const fmtDate=(s)=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(`${s}T12:00:00`));
const stamp=()=>new Date().toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seeds=[
 ['Revisão de contrato de prestação de serviços','Contratos','Em análise','Alta','Operações'],
 ['Documentação para defesa do consumidor','Consumidor','Aguardando MG Cred','Urgente','Atendimento'],
 ['Atualização da política de privacidade','LGPD','Em andamento','Normal','Tecnologia'],
 ['Aprovação da minuta de parceria comercial','Societário','Aguardando MG Cred','Alta','Diretoria'],
 ['Orientação sobre jornada de trabalho','Trabalhista','Aguardando Jurídico','Normal','Pessoas'],
 ['Validação de assinatura de aditivo','Contratos','Aguardando MG Cred','Normal','Financeiro'],
 ['Parecer sobre nova campanha comercial','Consultivo','Nova','Normal','Marketing'],
 ['Revisão do código de conduta','Compliance','Em análise','Normal','Pessoas'],
 ['Informações sobre contestação de cobrança','Cível','Aguardando MG Cred','Alta','Atendimento'],
 ['Análise de notificação extrajudicial','Notificação','Em andamento','Alta','Financeiro'],
 ['Consulta sobre contrato de tecnologia','Contratos','Nova','Normal','Tecnologia'],
 ['Organização dos documentos societários','Societário','Em análise','Normal','Diretoria'],
 ['Parecer sobre cláusula de confidencialidade','Parecer','Concluída','Normal','Operações']
];
let serial=36;
const demands=seeds.map((s,i)=>({id:`JUR-${now.getFullYear()}-${String(24+i).padStart(3,'0')}`,subject:s[0],category:s[1],status:s[2],priority:s[3],department:s[4],requester:'Equipe MG Cred (exemplo)',owner:'Jurídico',description:'Registro fictício para demonstração. Avaliar a solicitação, reunir os documentos e orientar a área responsável sobre os próximos passos.',created:day(-12+i),files:[],history:[{time:'Exemplo demonstrativo',text:'Solicitação recebida pelo Jurídico.'}]}));
const processes=Array.from({length:8},(_,i)=>({id:`PROC-DEMO-${String(i+1).padStart(3,'0')}`,title:['Revisão de obrigação contratual','Contestação de cobrança','Relação de consumo','Prestação de serviços'][i%4],party:`Parte fictícia ${String.fromCharCode(65+i)}`,court:['TJMG','TJSP','TRT-3'][i%3],phase:['Defesa','Instrução','Recurso','Acordo'][i%4],risk:['Baixo','Médio','Baixo','Alto'][i%4],value:[18000,42000,15000,68000,24000,12000,35000,21000][i],status:'Ativo'}));
const tasks=[
 {id:1,title:'Enviar documentos para defesa',due:day(1),owner:'MG Cred · Atendimento',priority:'Urgente',origin:demands[1].id,done:false},
 {id:2,title:'Revisar minuta de parceria',due:day(2),owner:'Jurídico',priority:'Alta',origin:demands[3].id,done:false},
 {id:3,title:'Validar política de privacidade',due:day(5),owner:'Jurídico',priority:'Normal',origin:demands[2].id,done:false},
 {id:4,title:'Consolidar documentos societários',due:day(12),owner:'MG Cred · Diretoria',priority:'Normal',origin:demands[11].id,done:false}
];
const activity=[{time:'Exemplo · hoje, 10:42',text:'Jurídico iniciou a revisão do contrato de serviços.'},{time:'Exemplo · hoje, 09:18',text:'Solicitados documentos à área de Atendimento.'},{time:'Exemplo · ontem, 16:30',text:'Concluído parecer sobre confidencialidade.'}];
let currentPage='dashboard', selectedId=null, demandQuery='', demandStatus='', processQuery='';
const $=s=>document.querySelector(s);
const isOpen=d=>!['Concluída','Arquivada'].includes(d.status);
const pending=()=>demands.filter(d=>d.status==='Aguardando MG Cred');
const upcoming=()=>tasks.filter(t=>!t.done&&t.due>=day(0)&&t.due<=day(7)).sort((a,b)=>a.due.localeCompare(b.due));
const statusClass=s=>s==='Concluída'||s==='Baixo'?'green':s==='Urgente'||s==='Alto'?'red':s==='Aguardando MG Cred'||s==='Alta'||s==='Médio'?'amber':'blue';
const badge=s=>`<span class="badge ${statusClass(s)}">${esc(s)}</span>`;
const money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const pageNames={dashboard:'Visão geral',demandas:'Demandas',processos:'Processos',tarefas:'Tarefas / Prazos',documentos:'Documentos',relatorios:'Relatórios',governanca:'Compliance & LGPD',administracao:'Administração',busca:'Busca'};
const heading=(title,subtitle,action=true)=>`<div class="page-head"><div><span class="eyebrow">PORTAL JURÍDICO / MG CRED</span><h1>${title}</h1><p class="muted">${subtitle}</p></div>${action?'<button class="primary" data-action="new">＋ Nova solicitação jurídica</button>':''}</div>`;
function metrics(){return `<div class="metrics">${[
 ['Demandas abertas',demands.filter(isOpen).length,'Em acompanhamento','demandas','▤',''],
 ['Prazos próximos',upcoming().length,'Nos próximos 7 dias','tarefas','◷',''],
 ['Processos ativos',processes.filter(p=>p.status==='Ativo').length,'Carteira de processos','processos','⚖',''],
 ['Aguardando MG Cred',pending().length,'Providências da sua equipe','demandas','↗','attention']
 ].map(([label,value,caption,page,icon,style])=>`<button class="metric ${style}" data-action="metric" data-target="${page}" data-pending="${style?'yes':''}"><span class="metric-top">${label}<span class="metric-icon" aria-hidden="true">${icon}</span></span><strong>${value}</strong><small>${caption}</small></button>`).join('')}</div>`;}
function demandTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Solicitação</th><th>Categoria</th><th>Status</th><th>Prioridade</th></tr></thead><tbody>${rows.map(d=>`<tr><td><button class="row-link" data-action="detail" data-id="${d.id}">${esc(d.subject)}</button><small>${d.id} · ${esc(d.department)}</small></td><td>${esc(d.category)}</td><td>${badge(d.status)}</td><td>${badge(d.priority)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma demanda encontrada com esses filtros.</div>';}
function dashboard(){return heading('Jurídico MG Cred','Suas prioridades, prazos e decisões em um só lugar.')+metrics()+`<div class="dashboard-grid">
 <section class="panel"><div class="panel-head"><div><h2>Próximos prazos</h2><p>Atenção aos próximos 7 dias</p></div><a class="text-button" href="#tarefas">Ver todos →</a></div>${upcoming().map(t=>`<div class="deadline"><div class="date-tile"><strong>${t.due.slice(-2)}</strong><small>${fmtDate(t.due).split(' ')[2]??new Date(t.due+'T12:00:00').toLocaleDateString('pt-BR',{month:'short'})}</small></div><div class="deadline-info"><button class="row-link" data-action="detail" data-id="${t.origin}">${esc(t.title)}</button><p>${esc(t.owner)} · ${t.origin}</p></div>${badge(t.priority)}</div>`).join('')||'<div class="empty">Nenhum prazo pendente nos próximos 7 dias.</div>'}</section>
 <section class="panel"><div class="panel-head"><div><h2>Precisa da MG Cred</h2><p>Providências para o Jurídico avançar</p></div><span class="pill-number">${pending().length}</span></div>${pending().slice(0,4).map(d=>`<div class="pending-card"><span class="pending-icon" aria-hidden="true">↗</span><div><h3>${esc(d.subject)}</h3><p>${esc(d.department)} · ${d.id}</p></div><button class="subtle" data-action="detail" data-id="${d.id}" aria-label="Abrir ${esc(d.subject)}">›</button></div>`).join('')||'<div class="empty">Tudo em dia. Nenhuma providência pendente.</div>'}</section>
 <section class="panel span-all"><div class="panel-head"><div><h2>Demandas em destaque</h2><p>Solicitações recentes em acompanhamento</p></div><a class="text-button" href="#demandas">Ver demandas →</a></div>${demandTable(demands.filter(isOpen).slice(0,4))}</section>
 <section class="panel span-all"><div class="panel-head"><h2>Últimas movimentações</h2><span class="muted">Histórico da sessão</span></div><div class="timeline">${activity.slice(0,3).map(a=>`<div class="event"><small>${esc(a.time)}</small><p>${esc(a.text)}</p></div>`).join('')}</div></section></div>`;}
function demandsPage(){return heading('Demandas jurídicas','Acompanhe cada solicitação, da abertura à conclusão.')+`<section class="panel"><div class="toolbar"><input id="demand-search" aria-label="Buscar demanda" placeholder="Buscar assunto, código ou setor" value="${esc(demandQuery)}"><select id="status-filter" aria-label="Filtrar por status"><option value="">Todos os status</option>${statuses.map(s=>`<option ${s===demandStatus?'selected':''}>${s}</option>`).join('')}</select></div><div id="demand-results"></div></section>`;}
function updateDemandResults(){const q=demandQuery.toLocaleLowerCase('pt-BR');$('#demand-results').innerHTML=demandTable(demands.filter(d=>(!demandStatus||d.status===demandStatus)&&`${d.subject} ${d.id} ${d.department}`.toLocaleLowerCase('pt-BR').includes(q)));}
function processesPage(){return heading('Processos','Visão executiva da carteira judicial fictícia.',false)+`<div class="notice">8 registros de exemplo. A importação do Excel será conectada após o mapeamento da sua planilha.</div><section class="panel"><div class="toolbar"><input id="process-search" aria-label="Buscar processo" placeholder="Buscar processo, parte ou tribunal" value="${esc(processQuery)}"></div><div id="process-results"></div></section>`;}
function updateProcessResults(){const rows=processes.filter(p=>`${p.id} ${p.title} ${p.party} ${p.court}`.toLocaleLowerCase('pt-BR').includes(processQuery.toLocaleLowerCase('pt-BR')));$('#process-results').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Processo / assunto</th><th>Tribunal</th><th>Fase</th><th>Valor da causa</th><th>Risco</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.title)}<small>${p.id} · ${p.party}</small></td><td>${p.court}</td><td>${p.phase}</td><td>${money(p.value)}</td><td>${badge(p.risk)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum processo encontrado.</div>';}
function tasksPage(){return heading('Tarefas / Prazos','Providências, responsáveis e datas para acompanhamento.',false)+`<section class="panel"><div class="panel-head"><h2>Agenda de providências</h2><span class="muted">${tasks.filter(t=>!t.done).length} pendentes</span></div>${tasks.map(t=>`<div class="check-row ${t.done?'done':''}"><input type="checkbox" id="task-${t.id}" data-task="${t.id}" ${t.done?'checked':''}><label for="task-${t.id}">${esc(t.title)}<small>${esc(t.owner)} · ${fmtDate(t.due)} · ${t.origin}</small></label>${badge(t.priority)}</div>`).join('')}</section>`;}
function documentsPage(){const list=demands.flatMap(d=>d.files.map(f=>({...f,demand:d})));return heading('Documentos','Anexos das solicitações criadas nesta demonstração.')+`<div class="notice">Anexe arquivos fictícios ao criar uma solicitação. Eles ficam disponíveis nesta sessão e desaparecem ao recarregar a página.</div><section class="panel"><div class="panel-head"><h2>Documentos da sessão</h2><span class="muted">${list.length} arquivo(s)</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Arquivo</th><th>Demanda</th><th>Tamanho</th><th>Ação</th></tr></thead><tbody>${list.map(f=>`<tr><td>${esc(f.name)}</td><td><button class="row-link" data-action="detail" data-id="${f.demand.id}">${f.demand.id}</button></td><td>${Math.max(1,Math.round(f.size/1024))} KB</td><td><a class="text-button" href="${f.url}" download="${esc(f.name)}">Baixar</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum anexo nesta sessão.<br>Crie uma solicitação para testar o envio de um documento.</div>'}</section>`;}
function reportsPage(){const usedCategories=categories.filter(c=>demands.some(d=>d.category===c));return heading('Relatórios executivos','Indicadores calculados a partir dos dados desta demonstração.',false)+metrics()+`<div class="section-grid"><section class="panel"><div class="panel-head"><h2>Demandas por área</h2><span class="muted">${demands.length} no total</span></div><div class="panel-body">${usedCategories.map(c=>{const n=demands.filter(d=>d.category===c).length;return `<div class="bar-item"><div class="bar-label"><span>${c}</span><strong>${n}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${n/demands.length*100}%"></div></div></div>`}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Risco da carteira</h2><span class="badge">Dados fictícios</span></div><div class="panel-body">${['Baixo','Médio','Alto'].map(r=>`<div class="risk-line"><span>${badge(r)}</span><strong>${processes.filter(p=>p.risk===r).length} processos</strong><span>${money(processes.filter(p=>p.risk===r).reduce((s,p)=>s+p.value,0))}</span></div>`).join('')}<p class="help">Soma dos valores das causas por classificação de risco. Não representa provisão contábil.</p><hr style="border:0;border-top:1px solid var(--border);margin:24px 0"><h3>Situação das demandas</h3>${statuses.filter(s=>demands.some(d=>d.status===s)).map(s=>`<div class="risk-line"><span>${s}</span><strong>${demands.filter(d=>d.status===s).length}</strong></div>`).join('')}</div></section></div>`;}
function governancePage(){return heading('Compliance & LGPD','Acompanhamento das solicitações de governança.',false)+`<div class="section-grid"><section class="panel"><div class="panel-head"><h2>Compliance</h2><span class="badge">Expansão futura</span></div><div class="panel-body"><p class="muted">O módulo completo está previsto para a fase 3.</p><ul class="governance-list"><li>Políticas e treinamentos</li><li>Ocorrências e planos de ação</li><li>Controles e documentos</li></ul><button class="secondary" data-action="new-category" data-category="Compliance">Abrir demanda de Compliance</button></div></section><section class="panel"><div class="panel-head"><h2>LGPD</h2><span class="badge">Expansão futura</span></div><div class="panel-body"><p class="muted">O módulo completo está previsto para a fase 3.</p><ul class="governance-list"><li>Solicitações de titulares</li><li>Incidentes e registro de tratamento</li><li>Políticas, documentos e prazos</li></ul><button class="secondary" data-action="new-category" data-category="LGPD">Abrir demanda de LGPD</button></div></section><section class="panel span-all"><div class="panel-head"><h2>Demandas de governança</h2></div>${demandTable(demands.filter(d=>['Compliance','LGPD'].includes(d.category)))}</section></div>`;}
function adminPage(){return heading('Administração','Evolução da demonstração para o portal com acesso protegido.',false)+`<div class="notice">Esta versão não possui login nem permissões reais. A indicação “Administrador Jurídico” identifica apenas a visão demonstrada.</div><div class="section-grid"><section class="panel"><div class="panel-head"><h2>Administrador Jurídico</h2><span class="badge">Perfil previsto</span></div><div class="panel-body"><ul class="governance-list"><li>Gerenciar demandas e processos</li><li>Atribuir responsáveis e alterar status</li><li>Administrar usuários e permissões</li><li>Consultar o histórico completo</li></ul></div></section><section class="panel"><div class="panel-head"><h2>Usuário MG Cred</h2><span class="badge">Perfil previsto</span></div><div class="panel-body"><ul class="governance-list"><li>Consultar informações autorizadas</li><li>Abrir e acompanhar solicitações</li><li>Responder e enviar documentos</li><li>Visualizar relatórios permitidos</li></ul></div></section><section class="panel span-all"><div class="panel-head"><h2>Próximo incremento: acesso e dados persistentes</h2></div><div class="panel-body"><p class="muted">Autenticação, permissões no servidor, banco de dados, documentos protegidos e importação do Excel precisam ser implementados antes do uso com informações reais.</p></div></section></div>`;}
const pages={dashboard:referenceDashboard,demandas:demandsPage,processos:processesPage,tarefas:tasksPage,documentos:documentsPage,relatorios:reportsPage,governanca:governancePage,administracao:adminPage,busca:searchPage};
function render(){const name=location.hash.slice(1);currentPage=pages[name]?name:'dashboard';$('#main').innerHTML=pages[currentPage]();$('#breadcrumb').textContent=pageNames[currentPage];document.title=`${pageNames[currentPage]} · Jurídico MG Cred`;document.querySelectorAll('[data-page]').forEach(a=>{const active=a.dataset.page===currentPage;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#nav-count').textContent=demands.filter(isOpen).length;if(currentPage==='demandas')updateDemandResults();if(currentPage==='processos')updateProcessResults();}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function openRequest(category){$('#request-form').reset();$('#request-error').textContent='';if(category)$('#category').value=category;$('#request-dialog').showModal();}
function addActivity(text){activity.unshift({time:stamp(),text});}
function detail(id){const d=demands.find(x=>x.id===id);if(!d)return;selectedId=id;$('#detail-content').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${d.id}</span><h2 id="detail-title">${esc(d.subject)}</h2></div><button class="close subtle" aria-label="Fechar detalhes">×</button></div><div class="detail-meta">${badge(d.status)}${badge(d.priority)}<span>${esc(d.category)}</span></div><p class="detail-description">${esc(d.description)}</p><p class="muted">Solicitante: ${esc(d.requester)} · ${esc(d.department)}<br>Responsável: ${esc(d.owner)} · Abertura: ${fmtDate(d.created)}</p><label>Status da demanda<select id="detail-status">${statuses.map(s=>`<option ${s===d.status?'selected':''}>${s}</option>`).join('')}</select></label><p class="help">Alterações demonstrativas registradas no histórico abaixo.</p><h3 style="margin-top:22px">Anexos (${d.files.length})</h3>${d.files.length?`<ul class="files">${d.files.map(f=>`<li><a href="${f.url}" download="${esc(f.name)}">↓ ${esc(f.name)}</a></li>`).join('')}</ul>`:'<p class="muted">Nenhum arquivo anexado.</p>'}<h3 style="margin-top:22px">Histórico e mensagens</h3><ul class="history">${d.history.map(h=>`<li><small>${esc(h.time)}</small>${esc(h.text)}</li>`).join('')}</ul><form id="message-form"><label>Adicionar mensagem<textarea name="message" rows="2" required maxlength="2000" placeholder="Registre uma atualização fictícia"></textarea></label><div class="dialog-actions"><button class="primary">Registrar mensagem</button></div></form>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function validateSubmission(data,files){for(const key of ['subject','description','requester','department'])if(!String(data.get(key)||'').trim())throw Error('Preencha assunto, descrição, solicitante e setor.');if(files.length>5||files.some(f=>f.size>5*1024*1024))throw Error('Selecione até 5 arquivos de no máximo 5 MB cada.');}
$('#category').innerHTML=categories.map(c=>`<option>${c}</option>`).join('');
$('#request-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);const files=Array.from(event.target.elements.attachments.files);try{validateSubmission(data,files);}catch(e){$('#request-error').textContent=e.message;return;}const id=`JUR-${now.getFullYear()}-${String(++serial).padStart(3,'0')}`;const d={id,subject:data.get('subject').trim(),description:data.get('description').trim(),category:data.get('category'),priority:data.get('priority'),requester:data.get('requester').trim(),department:data.get('department').trim(),status:'Nova',owner:'Jurídico',created:day(0),files:files.map(f=>({name:f.name,size:f.size,url:URL.createObjectURL(f)})),history:[{time:stamp(),text:'Solicitação criada na demonstração.'}]};demands.unshift(d);addActivity(`${id}: nova solicitação recebida.`);$('#request-dialog').close();demandQuery='';demandStatus='';location.hash='demandas';render();detail(id);notify(`Solicitação ${id} criada nesta sessão.`);});
document.addEventListener('click',event=>{const close=event.target.closest('.close');if(close){close.closest('dialog').close();return;}const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='new')openRequest();if(a==='new-category')openRequest(b.dataset.category);if(a==='detail')detail(b.dataset.id);if(a==='metric'){demandStatus=b.dataset.pending==='yes'?'Aguardando MG Cred':'';demandQuery='';location.hash=b.dataset.target;render();}});
document.addEventListener('input',event=>{if(event.target.id==='demand-search'){demandQuery=event.target.value;updateDemandResults();}if(event.target.id==='process-search'){processQuery=event.target.value;updateProcessResults();}});
document.addEventListener('change',event=>{if(event.target.id==='status-filter'){demandStatus=event.target.value;updateDemandResults();}if(event.target.id==='detail-status'){const d=demands.find(x=>x.id===selectedId);const previous=d.status;d.status=event.target.value;d.history.unshift({time:stamp(),text:`Status alterado de “${previous}” para “${d.status}”.`});addActivity(`${d.id}: ${d.status}.`);render();detail(d.id);notify('Status atualizado nesta sessão.');}if(event.target.dataset.task){const t=tasks.find(x=>x.id===Number(event.target.dataset.task));t.done=event.target.checked;addActivity(`Tarefa ${t.done?'concluída':'reaberta'}: ${t.title}.`);render();notify(t.done?'Tarefa concluída.':'Tarefa reaberta.');}});
document.addEventListener('submit',event=>{if(event.target.id!=='message-form')return;event.preventDefault();const message=event.target.elements.message.value.trim();if(!message){event.target.elements.message.setCustomValidity('Escreva uma mensagem.');event.target.elements.message.reportValidity();event.target.elements.message.oninput=()=>event.target.elements.message.setCustomValidity('');return;}const d=demands.find(x=>x.id===selectedId);d.history.unshift({time:stamp(),text:`Administrador Jurídico: ${message}`});addActivity(`Nova mensagem em ${d.id}.`);render();detail(d.id);notify('Mensagem registrada nesta sessão.');});
$('.mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',String(open));});
window.addEventListener('hashchange',()=>{render();$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');$('#main').focus();});
render();
// Progressive enhancement: browsers without WebMCP retain the complete interface.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_legal_request',title:'Abrir solicitação jurídica',description:'Abre o formulário demonstrativo. Não cria nem envia uma solicitação.',inputSchema:{type:'object',properties:{category:{type:'string',enum:categories}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='category')||(input.category!==undefined&&!categories.includes(input.category)))throw Error('Categoria inválida.');if($('#request-dialog').open)throw Error('O formulário já está aberto.');openRequest(input.category);return {formOpen:true,submitted:false};}})).catch(()=>{});}catch{}}
window.addEventListener('pagehide',()=>demands.forEach(d=>d.files.forEach(f=>URL.revokeObjectURL(f.url))),{once:true});
